import {invoiceDate} from './invoice-core.mjs';
const enc=new TextEncoder();
export function buildImagePdf(images){const chunks=[];const offsets=[0];let length=0;const push=v=>{const b=typeof v==='string'?enc.encode(v):v;chunks.push(b);length+=b.length;};const obj=(id,parts)=>{offsets[id]=length;push(`${id} 0 obj\n`);for(const p of parts)push(p);push('\nendobj\n');};push('%PDF-1.4\n');obj(1,['<< /Type /Catalog /Pages 2 0 R >>']);obj(2,[`<< /Type /Pages /Count ${images.length} /Kids [${images.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`]);images.forEach((image,i)=>{const page=3+i*3,img=page+1,stream=page+2;obj(page,[`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im${i} ${img} 0 R >> >> /Contents ${stream} 0 R >>`]);obj(img,[`<< /Type /XObject /Subtype /Image /Width ${image.width} /Height ${image.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.bytes.length} >>\nstream\n`,image.bytes,'\nendstream']);const content=`q\n595.28 0 0 841.89 0 0 cm\n/Im${i} Do\nQ`;obj(stream,[`<< /Length ${enc.encode(content).length} >>\nstream\n${content}\nendstream`]);});const start=length;push(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);for(let i=1;i<offsets.length;i++)push(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`);push(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);const bytes=new Uint8Array(length);let at=0;for(const c of chunks){bytes.set(c,at);at+=c.length;}return bytes;}
export function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
export async function invoicePdf(invoice){const W=1240,H=1754,pages=[];let canvas,ctx,y;const money=n=>new Intl.NumberFormat('en-US').format(n);const text=(s,x,yy,size=23,color='#173e36',align='right',weight='normal')=>{ctx.fillStyle=color;ctx.font=`${weight} ${size}px Tahoma,Arial,sans-serif`;ctx.textAlign=align;ctx.direction=align==='left'?'ltr':'rtl';ctx.fillText(String(s),x,yy);};const line=(yy)=>{ctx.strokeStyle='#dce6df';ctx.beginPath();ctx.moveTo(65,yy);ctx.lineTo(W-65,yy);ctx.stroke();};const wrap=(s,max,size=23)=>{ctx.font=`${size}px Tahoma,Arial,sans-serif`;const lines=[];let current='';for(const word of String(s||'').split(/\s+/)){if(ctx.measureText(word).width>max){if(current){lines.push(current);current='';}let part='';for(const ch of word){if(ctx.measureText(part+ch).width>max){lines.push(part);part='';}part+=ch;}current=part;}else if(current&&ctx.measureText(current+' '+word).width>max){lines.push(current);current=word;}else current+=(current?' ':'')+word;}if(current)lines.push(current);return lines.length?lines:[''];};const paragraph=(label,value,size=23)=>{const lines=wrap(`${label}${value}`,1100,size);for(const l of lines){text(l,1175,y,size);y+=33;}y+=6;};
function newPage(){canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);pages.push(canvas);ctx.fillStyle='#155e4a';ctx.fillRect(0,0,W,18);text('مستودع العاصمة',1175,85,39,'#155e4a','right','bold');text('فاتورة طلب مبدئية',1175,130,25);text(invoice.id,65,80,22,'#155e4a','left','bold');text(invoiceDate(invoice.createdAt),65,120,19,'#62776e','left');text('واتساب الطلبات: \u2066+963967765704\u2069',1175,173,20);line(195);y=235;}
function tableHead(){ctx.fillStyle='#eaf4ef';ctx.fillRect(65,y-28,1110,48);text('#',1150,y,20);text('الصنف',1080,y,22);text('الكمية',535,y,21);text('سعر الوحدة',380,y,21);text('الإجمالي',210,y,21);y+=40;}
newPage();paragraph('الصيدلية: ',invoice.pharmacy.name);paragraph('العنوان: ',[invoice.pharmacy.city,invoice.pharmacy.address].filter(Boolean).join(' - '));if(invoice.pharmacy.phone||invoice.pharmacy.contact)paragraph('التواصل: ',[invoice.pharmacy.contact,invoice.pharmacy.phone].filter(Boolean).join(' / '));if(invoice.previousId)paragraph('نسخة جديدة بدلًا من: ',invoice.previousId,18);y+=15;tableHead();
invoice.items.forEach((item,i)=>{const ar=wrap(item.ar,500,23),en=wrap(item.en,500,17);const rh=Math.max(88,ar.length*30+en.length*23+24);if(y+rh>1605){newPage();text(`الصيدلية: ${invoice.pharmacy.name}`,1175,y,22);y+=45;tableHead();}text(i+1,1150,y+20,20);ar.forEach((l,j)=>text(l,1080,y+20+j*30,23));en.forEach((l,j)=>text(l,580,y+22+ar.length*30+j*23,17,'#6b7b74','left'));text(item.qty,520,y+20,22);text(money(item.unitPrice),380,y+20,22);text(money(item.total),210,y+20,22);y+=rh;line(y-12);});
const noteLines=wrap(invoice.pharmacy.notes,1100,21);const needed=635+noteLines.length*33;if(y+needed>1625){newPage();paragraph('الصيدلية: ',invoice.pharmacy.name);}y+=10;ctx.fillStyle='#eaf4ef';ctx.fillRect(65,y-5,1110,85);text('الإجمالي التقديري',1140,y+28,25);text(`${money(invoice.total)} ل.س`,95,y+47,34,'#155e4a','left','bold');y+=118;paragraph('',`${invoice.items.length} صنف / ${invoice.count} عبوة. الأسعار والتوفر تحتاج تأكيد المستودع.`,20);paragraph('','الإجمالي لا يشمل التوصيل. لا تُعد هذه الفاتورة إثباتًا للدفع.',20);if(invoice.pharmacy.notes)paragraph('ملاحظات الطلب: ',invoice.pharmacy.notes,21);y+=12;paragraph('تاريخ التسليم: ','........ / ........ / ................',22);paragraph('ملاحظات الاستلام: ','................................................................................',21);const top=y+10;
for(const [x,label] of [[645,'ممثل المستودع / المُسلّم'],[65,'ممثل الصيدلية / المستلم']]){ctx.strokeStyle='#cbdcd2';ctx.strokeRect(x,top,530,250);text(label,x+505,top+35,23,'#155e4a','right','bold');text('الاسم: ................................',x+505,top+78,21);text('التوقيع بالقلم:',x+505,top+122,22);text('..............................................',x+505,top+176,22);text('الختم: ................................',x+505,top+222,21);}
y=top+285;paragraph('','تُملأ خانات الاستلام والتوقيع بالقلم على النسخة المطبوعة عند تسليم المنتجات.',19);

const images=pages.map((page,i)=>{const c=page.getContext('2d');c.fillStyle='#72867c';c.font='18px Tahoma,Arial';c.textAlign='center';c.fillText(`${invoice.id}   |   ${i+1} / ${pages.length}`,W/2,H-38);const raw=atob(page.toDataURL('image/jpeg',.94).split(',')[1]);return{width:W,height:H,bytes:Uint8Array.from(raw,c=>c.charCodeAt(0))};});return new Blob([buildImagePdf(images)],{type:'application/pdf'});}
